export const adminActionLog = pgTable(
  "admin_action_log",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    actorProfileId: uuid("actor_profile_id"),
    actorLabel: text("actor_label").notNull(),
    actorRole: text("actor_role").notNull(),
    action: text().notNull(),
    targetType: text("target_type").notNull(),
    targetId: uuid("target_id"),
    targetLabel: text("target_label").notNull(),
    details: jsonb().default({}).notNull(),
    occurredAt: timestamp("occurred_at", { withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    index("idx_admin_action_log_occurred").using(
      "btree",
      table.occurredAt.desc().nullsFirst().op("timestamptz_ops"),
    ),
    foreignKey({
      columns: [table.actorProfileId],
      foreignColumns: [profiles.id],
      name: "admin_action_log_actor_profile_id_fkey",
    }).onDelete("set null"),
    pgPolicy("admin_action_log_select", {
      as: "permissive",
      for: "select",
      to: ["public"],
      using: sql`is_platform_admin()`,
    }),
    pgPolicy("service_role_all", {
      as: "permissive",
      for: "all",
      to: ["service_role"],
    }),
    check(
      "admin_action_log_action_check",
      sql`action = ANY (ARRAY['admin_granted'::text, 'admin_revoked'::text, 'account_suspended'::text, 'account_reactivated'::text, 'municipality_registered'::text, 'vet_license_validated'::text, 'vet_license_rejected'::text])`,
    ),
    check(
      "admin_action_log_action_target_check",
      sql`CHECK (
CASE
    WHEN (action = 'municipality_registered'::text) THEN (target_type = 'municipality'::text)
    WHEN (action = ANY (ARRAY['vet_license_validated'::text, 'vet_license_rejected'::text])) THEN (target_type = 'vet_professional'::text)
    ELSE (target_type = 'profile'::text)
END)`,
    ),
    check(
      "admin_action_log_target_type_check",
      sql`target_type = ANY (ARRAY['profile'::text, 'municipality'::text, 'vet_professional'::text])`,
    ),
  ],
);

